                self.run_argv(upload)?
            }
            _ => {
                return Err(GraphError::UnsupportedRelease {
                    feature: UnsupportedReleaseFeature::Ecosystem,
                })
            }
        };
        let outcome = match id.package.ecosystem() {
            Ecosystem::Cargo => registry_argv::classify_cargo_output(&output),
            Ecosystem::Npm => registry_argv::classify_npm_publish_output(&output),
            Ecosystem::Pypi => registry_argv::classify_twine_output(&output),
            _ => {
                return Err(GraphError::UnsupportedRelease {
                    feature: UnsupportedReleaseFeature::Ecosystem,
                })
            }
        }
        .map_err(|source| GraphError::Registry {
            package: package_name.clone(),
            source,
        })?;
        if matches!(outcome, PublishOutcome::Published)
            && ecosystem_requires_registry_confirmation(id.package.ecosystem())
        {
            let is_published = match id.package.ecosystem() {
                Ecosystem::Npm => poll_until_published(
                    || self.npm_version_is_published(package_name, version, registry.endpoint.as_deref()),
                    REGISTRY_CONFIRMATION_MAX_RETRIES,
                    registry_confirmation_backoff,
                    std::thread::sleep,
                )?,
                Ecosystem::Cargo => {
                    let registry_key = (registry.key.as_str() != RegistryKey::CRATES_IO).then(|| registry.key.as_str());
                    poll_until_published(
                        || self.cargo_version_is_published(package_name, version, registry_key),
                        REGISTRY_CONFIRMATION_MAX_RETRIES,
                        registry_confirmation_backoff,
                        std::thread::sleep,
                    )?
                }
                other => {
                    return Err(GraphError::ReleaseInvariant {
                        detail: format!(
                            "ecosystem_requires_registry_confirmation returned true for {other:?}, which has no confirmation check wired"
                        ),
                    })
                }
            };
            require_registry_confirmation(is_published, package_name, version)?;
        }
        Ok(match outcome {
            PublishOutcome::Published => OperationOutcome::Published,
            PublishOutcome::AlreadyPublished => OperationOutcome::AlreadySatisfied,
        })
    }
}

/// Ecosystems whose publish gets confirmed against the registry before the
/// operation is marked done. Npm and Cargo are checked; PyPI has the
/// identical propagation-lag gap, deliberately deferred -- no PyPI package
/// or credentials in this workspace to test a fix against. The single
/// source of truth `dispatch_registry` actually consults, so a test on this
/// function directly proves the runtime gate, not a copy of it.
fn ecosystem_requires_registry_confirmation(ecosystem: Ecosystem) -> bool {
    matches!(ecosystem, Ecosystem::Npm | Ecosystem::Cargo)
}

/// A successful publish-client exit isn't a receipt: confirms the registry
/// itself has caught up before treating the operation as done. If not, it
/// stays `Attempting` for reconciliation, reported via its own variant
/// rather than `ReleaseIntentStale`'s false "no operation was authorized".
fn require_registry_confirmation(is_published: bool, package: &str, version: &Version) -> Result<(), GraphError> {
    if is_published {
        return Ok(());
    }
    Err(GraphError::RegistryPublishUnconfirmed {
        package: package.to_string(),
        version: version.clone(),
    })
}

/// Retries after this many unconfirmed checks: 3 retries (4 checks total).
const REGISTRY_CONFIRMATION_MAX_RETRIES: u32 = 3;

/// Exponential backoff between confirmation checks: 2s, 4s, 8s (14s worst
/// case) -- registry index propagation is normally sub-second, so this only
/// costs time on the rare lagging case, not the common one.
fn registry_confirmation_backoff(retry: u32) -> std::time::Duration {
    std::time::Duration::from_secs(2u64.pow(retry + 1))
}

/// Retries `check` up to `max_retries` more times, sleeping `backoff(retry)`
/// between attempts, and returns as soon as it reports published. Returns
/// `Ok(false)` if it never does. `sleep` is injected so tests can verify the
/// retry count and schedule without a real wall-clock wait.
fn poll_until_published(
    mut check: impl FnMut() -> Result<bool, GraphError>,
    max_retries: u32,
    backoff: impl Fn(u32) -> std::time::Duration,
    sleep: impl Fn(std::time::Duration),
) -> Result<bool, GraphError> {
    for retry in 0..=max_retries {
        if check()? {
            return Ok(true);
        }
        if retry < max_retries {
            sleep(backoff(retry));
        }
    }
    Ok(false)
}

impl ValidatedReleaseIntent<'_> {
    /// Runs a [`registry_argv::Argv`] built by the pure argv layer. This is
    /// the only place `dispatch_registry` touches [`CommandRunner`] --
    /// everything about *what* to run (program, args, cwd) was already
    /// decided by `registry_argv`.
    fn run_argv(&self, argv: &registry_argv::Argv) -> Result<CommandOutput, GraphError> {
        let args: Vec<&str> = argv.args.iter().map(String::as_str).collect();
        Ok(self.runner.run(&argv.program, &args, &argv.cwd)?)
    }

    fn npm_version_is_published(
        &self,
        package_name: &str,
        version: &Version,
        registry: Option<&str>,
    ) -> Result<bool, GraphError> {
        let spec = format!("{package_name}@{}", version.render());
        let mut args = vec!["view", spec.as_str(), "--json"];
        if let Some(registry) = registry {
            args.extend(["--registry", registry]);
        }
        let output = self
            .runner
            .run_quiet("npm", &args, &self.prepared.root, std::time::Duration::from_secs(300))?;
        if output.success() {
            return Ok(!output.stdout_trimmed().is_empty());
        }
        let details = format!("{}\n{}", output.stdout, output.stderr).to_ascii_lowercase();
        if details.contains("e404")
            || details.contains("etarget")
            || details.contains("no matching version")
            || details.contains("is not in this registry")
        {
            return Ok(false);
        }
        Err(GraphError::ReleaseCommand {
            program: "npm".to_string(),
            args: args.iter().map(ToString::to_string).collect(),
            failure: CommandFailure::NonZeroExit {
                exit_code: output.exit_code,
                stderr: output.stderr,
            },
        })
    }

    fn cargo_version_is_published(
        &self,
        package_name: &str,
        version: &Version,
        registry_key: Option<&str>,
    ) -> Result<bool, GraphError> {
        let spec = format!("{package_name}@{}", version.render());
        let mut args = vec!["info", spec.as_str()];
        if let Some(registry) = registry_key {
            args.extend(["--registry", registry]);
        }
        let output = self
            .runner
            .run_quiet("cargo", &args, &self.prepared.root, std::time::Duration::from_secs(300))?;
        registry_argv::classify_cargo_info_output(&output).map_err(|source| GraphError::Registry {
            package: package_name.to_string(),
            source,
        })
    }

    fn dispatch_tag(
        &self,
        permit: &ApplyPermit,
        name: &TagName,
        target: &CommitSha,
        annotation: &str,
    ) -> Result<OperationOutcome, GraphError> {
        if let Some(observed) = self.observed_tag(name)? {
            return if observed.target == *target && observed.annotation == annotation {
                Ok(OperationOutcome::AlreadySatisfied)
            } else {
                Err(GraphError::ReleaseRemoteConflict {
                    conflict: RemoteConflict::TagTargetDiffers,
                })
            };
        }
        // Delegates to `GitAccess::create_tag` rather than inlining `git
        // tag` argv, so this inherits its `--` end-of-options separator
        // (defends `name` against being misread as a flag) on top of the
        // `--no-sign` this durable path has always needed (this repo's CI
        // sets `tag.gpgSign`/`commit.gpgsign` globally in some contexts,
        // with no tag-signing key available here).
        let git = GitAccess::discover(&self.prepared.root, self.runner);
        git.create_tag(
            name.as_str(),
            target,
            Some(annotation),
            TagSignPolicy::ForceUnsigned,
            permit,
        )?;
        let remote_endpoint = self.checked_git_remote()?.endpoint.clone();
        let push_args = ["push", remote_endpoint.as_str(), name.as_str()];
        let pushed = self.runner.run("git", &push_args, &self.prepared.root)?;
        if pushed.exit_code != Some(0) {
            return Err(GraphError::ReleaseCommand {
                program: "git".to_string(),
                args: push_args.iter().map(ToString::to_string).collect(),
                failure: CommandFailure::NonZeroExit {
                    exit_code: pushed.exit_code,
                    stderr: pushed.stderr,
                },
            });
        }
        if self
            .observed_tag(name)?
            .is_some_and(|observed| observed.target == *target && observed.annotation == annotation)
        {
            Ok(OperationOutcome::Published)
        } else {
            Err(GraphError::ReleaseRemoteConflict {
                conflict: RemoteConflict::TagNotObservedAfterPush,
            })
        }
    }

    fn dispatch_forge_release(&self, tag: &TagName) -> Result<OperationOutcome, GraphError> {
        let remote = self.checked_git_remote()?;
        let repository = remote
            .github_repository
            .as_ref()
            .ok_or(GraphError::ReleasePreconditionUnmet {
                requirement: ReleasePreconditionRequirement::GitHubRemote,
            })?
            .as_slug();
        match self.observed_forge_release_target(tag, &repository)? {
            ForgeReleaseObservation::Exact => return Ok(OperationOutcome::AlreadySatisfied),
            ForgeReleaseObservation::Conflict => {
                return Err(GraphError::ReleaseRemoteConflict {
                    conflict: RemoteConflict::ForgeReleaseDiffers,
                })
            }
            ForgeReleaseObservation::Missing => {}
        }
        let create_args = [
            "release",
            "create",
            tag.as_str(),
            "--repo",
            repository.as_str(),
            "--verify-tag",
            "--generate-notes",
        ];
        let created = self.runner.run("gh", &create_args, &self.prepared.root)?;
        if created.exit_code != Some(0) {
            return Err(GraphError::ReleaseCommand {
                program: "gh".to_string(),
                args: create_args.iter().map(ToString::to_string).collect(),
                failure: CommandFailure::NonZeroExit {
                    exit_code: created.exit_code,
                    stderr: created.stderr,
                },
            });
        }
        if self.observed_forge_release_target(tag, &repository)? == ForgeReleaseObservation::Exact {
            Ok(OperationOutcome::Published)
        } else {
            Err(GraphError::ReleaseRemoteConflict {
                conflict: RemoteConflict::ForgeReleaseNotObservedAfterCreate,
            })
        }
    }

    fn observed_tag(&self, name: &TagName) -> Result<Option<ObservedTag>, GraphError> {
        let reference = format!("refs/tags/{name}^{{commit}}");
        let rev_parse_args = ["rev-parse", "--verify", "--quiet", reference.as_str()];
        let observed = self.runner.run("git", &rev_parse_args, &self.prepared.root)?;
        if observed.exit_code != Some(0) {
            return Ok(None);
        }
        let target = CommitSha::parse(observed.stdout.trim()).map_err(|error| GraphError::ReleaseCommand {
            program: "git".to_string(),
            args: rev_parse_args.iter().map(ToString::to_string).collect(),
            failure: CommandFailure::MalformedOutput {
                detail: error.to_string(),
            },
        })?;
        let for_each_ref_target = format!("refs/tags/{name}");
        let for_each_ref_args = [
            "for-each-ref",
            "--format=%(objecttype)%00%(contents:subject)%00%(contents:body)",
            for_each_ref_target.as_str(),
        ];
        let details = self.runner.run("git", &for_each_ref_args, &self.prepared.root)?;
        if details.exit_code != Some(0) {
            return Err(GraphError::ReleaseCommand {
                program: "git".to_string(),
                args: for_each_ref_args.iter().map(ToString::to_string).collect(),
                failure: CommandFailure::NonZeroExit {
                    exit_code: details.exit_code,
                    stderr: details.stderr,
                },
            });
        }
        let line = details.stdout.trim_end_matches(['\r', '\n']);
        let mut fields = line.split('\0');
        let object_type = fields.next();
        let annotation = fields.next();
        let body = fields.next();
        if object_type != Some("tag") || body.is_none_or(|body| !body.trim().is_empty()) || fields.next().is_some() {
            return Err(GraphError::ReleaseCommand {
                program: "git".to_string(),
                args: for_each_ref_args.iter().map(ToString::to_string).collect(),
                failure: CommandFailure::MalformedOutput {
                    detail: format!("unexpected for-each-ref output: {line:?}"),
                },
            });
        }
        let annotation = annotation.ok_or_else(|| GraphError::ReleaseInvariant {
            detail: "for-each-ref line validated as `tag`/empty-body but carried no annotation field".to_string(),
        })?;
        Ok(Some(ObservedTag {
            target,
            annotation: annotation.to_string(),
        }))
    }

    fn observed_forge_release_target(
        &self,
        tag: &TagName,
        repository: &str,
    ) -> Result<ForgeReleaseObservation, GraphError> {
        let endpoint = format!("repos/{repository}/releases/tags/{tag}");
        let api_args = [
            "api",
            "--include",
            "--method",
//! Pure argv construction for "publish a package to its registry", plus
//! subprocess-output classification for the same three ecosystems (Cargo,
//! npm, PyPI).
//!
//! This module owns exactly two questions per ecosystem: *what command do we
//! run* (given package/plan facts and already-detected environment facts --
//! never a [`callisto_model::CommandRunner`] call of its own) and *what did
//! the finished command's output mean*. Actually invoking the command, and
//! any retry/backoff policy around a failed attempt, is the caller's job --
//! see `super::release::ValidatedReleaseIntent::dispatch_prepared`, the
//! durable release executor's single production publish path.
//!
//! A small amount of local filesystem reading happens here (the Cargo
//! on-disk version check, npm package-manager detection from lockfiles) --
//! that's "gathering the facts needed to build the right argv", not
//! executing a publish. It never shells out.

use std::path::{Path, PathBuf};
use std::time::Duration;

use callisto_manifests::WorkspaceCargoResolver;
use callisto_model::{
    normalize_pypi_package_name, CommandOutput, Ecosystem, NpmAccess, PackageId, PublishOutcome, RegistryError, Version,
};

use crate::error::GraphError;

/// Default fallback wait (seconds) when a registry does not supply a
/// `retry_after` value and the classifier cannot parse one from output.
const DEFAULT_RATE_LIMIT_WAIT_SECS: u64 = 60;

/// One subprocess invocation: program, args, and working directory. Building
/// this is the entire job of the `*_publish_argv` functions below --
/// executing it is the caller's.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Argv {
    pub program: String,
    pub args: Vec<String>,
    pub cwd: PathBuf,
}

// ---------------------------------------------------------------- cargo

/// Builds the exact `cargo publish` argv for one crate: `--manifest-path`
/// (so the caller can keep the workspace root as its own working directory)
/// plus `--locked`, so a stale `Cargo.lock` fails the publish immediately
/// instead of `cargo` silently re-resolving one at publish time.
/// `registry_key` is `Some` only for a non-default registry -- crates.io is
/// the implicit default and never needs `--registry`.
///
/// Before returning, verifies that the on-disk `Cargo.toml` version under
/// `package_dir` (resolving `version.workspace = true` against the
/// workspace root's `[workspace.package].version` when present) matches
/// `version` -- this is the one behavior `SubprocessRegistryClient` had that
/// the durable release executor's own `dispatch_registry` had silently
/// dropped: it catches the common mistake of running `release execute`
/// without first running `callisto version`, which would otherwise silently
/// publish the old on-disk version.
pub fn cargo_publish_argv(
    workspace_root: &Path,
    package_dir: &Path,
    package_name: &str,
    version: &Version,
    registry_key: Option<&str>,
) -> Result<Argv, GraphError> {
    verify_cargo_ondisk_version(workspace_root, package_dir, package_name, version)?;

    let manifest_path = workspace_root.join(package_dir).join("Cargo.toml");
    let mut args = vec![
        "publish".to_string(),
        "--manifest-path".to_string(),
        manifest_path.to_string_lossy().into_owned(),
        "--locked".to_string(),
    ];
    if let Some(reg) = registry_key {
        args.push("--registry".to_string());
        args.push(reg.to_string());
    }
    Ok(Argv {
        program: "cargo".to_string(),
        args,
        cwd: workspace_root.to_path_buf(),
    })
}

fn verify_cargo_ondisk_version(
    workspace_root: &Path,
    package_dir: &Path,
    package_name: &str,
    planned: &Version,
) -> Result<(), GraphError> {
    let manifest_path = workspace_root.join(package_dir).join("Cargo.toml");
    let contents = std::fs::read_to_string(&manifest_path).map_err(|error| GraphError::ReleaseInputRead {
        path: manifest_path.clone(),
        message: error.to_string(),
    })?;
    // Parse only the [package].version field -- no need for full CST. A
    // permissive `toml::Value` intermediate rather than a direct `String`
    // deserialization, because `version.workspace = true` (Cargo's
    // workspace-version-inheritance syntax) parses `version` as a table, not
    // a string.
    let parsed = toml::from_str::<toml::Value>(&contents).map_err(|error| GraphError::ReleaseInputRead {
        path: manifest_path.clone(),
        message: error.to_string(),
    })?;
    let version_value =
        parsed
            .get("package")
            .and_then(|p| p.get("version"))
            .ok_or_else(|| GraphError::ReleaseInputRead {
                path: manifest_path.clone(),
                message: "missing [package].version".to_string(),
            })?;

    let on_disk = if let Some(s) = version_value.as_str() {
        s.to_string()
    } else if version_value.get("workspace").and_then(toml::Value::as_bool) == Some(true) {
        let root_manifest_path = workspace_root.join("Cargo.toml");
        let resolver = WorkspaceCargoResolver::load(&root_manifest_path)?;
        let ws_version = resolver
            .workspace_version()?
            .ok_or_else(|| GraphError::ReleaseInputRead {
                path: root_manifest_path.clone(),
                message: "`version.workspace = true` but the workspace root has no [workspace.package].version"
                    .to_string(),
            })?;
        ws_version.render().to_string()
    } else {
        return Err(GraphError::ReleaseInputRead {
            path: manifest_path,
            message: "[package].version is neither a string nor a `{ workspace = true }` table".to_string(),
        });
    };

    let found = Version::parse(&on_disk, planned.grammar())?;
    if found != *planned {
        return Err(GraphError::OnDiskVersionDrift {
            package: PackageId::Prefixed {
                ecosystem: Ecosystem::Cargo,
                name: package_name.to_string(),
            },
            expected: planned.clone(),
            found,
        });
    }
    Ok(())
}

// ------------------------------------------------------------------ npm

/// The npm-compatible package manager a workspace uses, detected from
/// lockfile presence. Each one needs a materially different invocation to
/// publish a single named package out of a monorepo -- see
/// [`npm_publish_argv`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NpmPackageManager {
    Pnpm,
    Yarn,
    Bun,
    Npm,
}

/// Detects the npm-compatible package manager for `workspace_root` from
/// lockfile presence. Detection priority: pnpm > yarn > bun > npm (default).
///
/// This is real, live-today correctness content: the durable release
/// executor's `dispatch_registry` used to hardcode plain `npm publish`
/// regardless of which package manager a workspace actually uses, so a pnpm
/// or yarn workspace published with the wrong tool.
pub fn detect_npm_package_manager(workspace_root: &Path) -> NpmPackageManager {
    if workspace_root.join("pnpm-lock.yaml").exists() {
        NpmPackageManager::Pnpm
    } else if workspace_root.join("yarn.lock").exists() {
        NpmPackageManager::Yarn
    } else if workspace_root.join("bun.lockb").exists() || workspace_root.join("bun.lock").exists() {
        // bun.lockb is the legacy binary lockfile format; bun.lock (text) is
        // written by Bun >= 1.1.1. Both signal a bun-managed workspace.
        NpmPackageManager::Bun
    } else {
        NpmPackageManager::Npm
    }
}

/// Builds the npm-ecosystem publish argv for one package, given the
/// already-detected `package_manager` (see [`detect_npm_package_manager`]).
///
/// | Package manager | Program | Base args                                  |
/// |------------------|---------|--------------------------------------------|
/// | Pnpm             | `pnpm`  | `publish --filter <name> --no-git-checks`  |
/// | Yarn             | `yarn`  | `workspace <name> npm publish`             |
/// | Bun              | `bun`   | `publish` (run from `package_dir`)         |
/// | Npm              | `npm`   | `publish --workspace <name>`               |
///
/// `tag`/`access`/`registry` are appended to every variant's base args.
/// `package_dir` is only used for bun: it has no `--filter`/`--workspace`
/// flag to target one package by name, so it alone must run from the
/// package's own directory rather than the workspace root.
pub fn npm_publish_argv(
    workspace_root: &Path,
    package_dir: &Path,
    package_name: &str,
    package_manager: NpmPackageManager,
    tag: Option<&str>,
    access: Option<NpmAccess>,
    registry: Option<&str>,
) -> Argv {
    let mut extra: Vec<String> = Vec::new();
    if let Some(t) = tag {
        extra.push("--tag".to_string());
        extra.push(t.to_string());
    }
    if let Some(access) = access {
        extra.push("--access".to_string());
        extra.push(
            match access {
                NpmAccess::Public => "public",
                NpmAccess::Restricted => "restricted",
            }
            .to_string(),
        );
    }
    if let Some(reg) = registry {
        extra.push("--registry".to_string());
        extra.push(reg.to_string());
    }

    let (program, mut args, cwd) = match package_manager {
        NpmPackageManager::Pnpm => (
            "pnpm",
            vec![
                "publish".to_string(),
                "--filter".to_string(),
                package_name.to_string(),
                // pnpm >= 7 refuses to publish from a dirty working tree by
                // default. After `callisto version` stages manifest bumps,
                // the tree is always dirty until the operator commits, so
                // this bypasses the git-status check.
                "--no-git-checks".to_string(),
            ],
            workspace_root.to_path_buf(),
        ),
        NpmPackageManager::Yarn => (
            "yarn",
            vec![
                "workspace".to_string(),
                package_name.to_string(),
                "npm".to_string(),
                "publish".to_string(),
            ],
            workspace_root.to_path_buf(),
        ),
        NpmPackageManager::Bun => ("bun", vec!["publish".to_string()], workspace_root.join(package_dir)),
        NpmPackageManager::Npm => (
            "npm",
            vec![
                "publish".to_string(),
                "--workspace".to_string(),
                package_name.to_string(),
            ],
            workspace_root.to_path_buf(),
        ),
    };
    args.extend(extra);
    Argv {
        program: program.to_string(),
        args,
        cwd,
    }
}

// ----------------------------------------------------------------- pypi

/// Builds the two-step PyPI publish argv sequence: build the sdist and
/// wheel into `dist/`, then upload the exact `dist/<normalized-name>-
/// <version>*` glob via `twine upload --skip-existing`. Both steps run from
/// `package_dir` so `dist/` resolves to that package's own directory in a
/// monorepo, and neither ever builds into or uploads from a fresh temporary
/// directory -- `twine`'s own glob targets exactly the artifacts this
/// `python -m build` invocation just produced, not whatever else happens to
/// be sitting in `dist/`.
///
/// Package name is normalized to PEP 427 wheel-filename form (lowercased,
/// `-`/`.` -> `_`) before building the glob; `twine` expands the glob
/// internally, so the literal `*` is safe with no shell involved.
/// `index: Some` inserts `--repository-url <url>` before the glob, to target
/// a private index (Nexus/Artifactory PyPI proxy) instead of public PyPI.
pub fn pypi_publish_argv(
    workspace_root: &Path,
    package_dir: &Path,
    package_name: &str,
    version: &Version,
    index: Option<&str>,
) -> Vec<Argv> {
    let cwd = workspace_root.join(package_dir);
    let build = Argv {
        program: "python".to_string(),
        args: vec![
            "-m".to_string(),
            "build".to_string(),
            "--sdist".to_string(),
            "--wheel".to_string(),
            "--outdir".to_string(),
            "dist/".to_string(),
        ],
        cwd: cwd.clone(),
    };

    let normalized = normalize_pypi_package_name(package_name);
    let pattern = format!("dist/{normalized}-{}*", version.render());
    let mut upload_args = vec!["upload".to_string(), "--skip-existing".to_string()];
    if let Some(idx) = index {
        upload_args.push("--repository-url".to_string());
        upload_args.push(idx.to_string());
    }
    upload_args.push(pattern);
    let upload = Argv {
        program: "twine".to_string(),
        args: upload_args,
        cwd,
    };

    vec![build, upload]
}

// ---- shared output-classification helpers --------------------------------

fn combined_lower(output: &CommandOutput) -> String {
    format!("{}\n{}", output.stdout, output.stderr).to_lowercase()
}

/// Parses a numeric retry-after value (seconds) as reported by a registry
/// tool's output.
fn parse_retry_after(raw: &str) -> Option<Duration> {
    raw.trim().parse::<u64>().ok().map(Duration::from_secs)
}

/// Looks for a `retry after <N>` mention in already-lowercased text and
