    pub fn from_payloads(
        intent: &ReleaseIntent,
        validated: &ValidatedPayloadEntries,
    ) -> Result<Self, SuccessorError> {
        validated.validate_for(intent)?;
        let mut payloads = validated
            .entries
            .iter()
            .filter_map(|entry| match &entry.slot {
                ReleaseArtifactSlot::ProductAsset {
                    target,
                    artifact_kind,
                    file_name,
                    provenance_policy,
                    ..
                } => Some(MetadataPayload {
