        serde_json::to_vec(self).expect("closed metadata serializes")
    }

    pub fn from_canonical_json(bytes: &[u8]) -> Result<Self, SuccessorError> {
        let wire: ReleaseDistributionMetadataV1Wire =
            serde_json::from_slice(bytes).map_err(|_| SuccessorError::InvalidMetadata)?;
        let metadata = Self {
            schema_version: wire.schema_version,
            product_release: wire.product_release,
            intent_digest: wire.intent_digest,
            source_commit: wire.source_commit,
            payloads: wire.payloads,
            verification_policy: wire.verification_policy,
        };
        metadata.validate()?;
        if metadata.canonical_json() != bytes {
            return Err(SuccessorError::NonCanonicalMetadataBytes);
        }
        Ok(metadata)
    }

