        &self.source_commit
    }

    pub fn payloads(&self) -> &[MetadataPayload] {
        &self.payloads
    }

    pub fn verification_policy(&self) -> &ProvenancePolicy {
        &self.verification_policy
    }

    fn validate(&self) -> Result<(), SuccessorError> {
        if self.schema_version != Self::SCHEMA_VERSION
            || self.payloads.len() != ProductTarget::ALL.len()
            || self.payloads.windows(2).any(|pair| pair[0].target >= pair[1].target)
            || !ProductTarget::ALL.iter().zip(&self.payloads).all(|(target, payload)| {
                target == &payload.target
                    && payload.artifact_kind == target.artifact_kind()
                    && payload.file_name == target.file_name()
            })
            || self
                .payloads
                .iter()
                .any(|payload| payload.provenance_policy.validate().is_err())
            || self.verification_policy.validate().is_err()
            || self
                .payloads
                .iter()
                .any(|payload| payload.provenance_policy != self.verification_policy)
        {
            return Err(SuccessorError::InvalidMetadata);
        }
        Ok(())
    }
}

