// This is deliberately private until CUTOVER-1.  The public V1 release
// document is still consumed by graph and CLI; exposing this successor before
// those consumers move would create two competing durable contracts.
#[allow(dead_code)] // Staged private successor; CUTOVER-1 makes these the sole production contract.
mod successor {
    use super::*;

    const METADATA_FILE_NAME: &str = "callisto-release-metadata.json";
    const CHECKSUM_FILE_NAME: &str = "SHA256SUMS";

    #[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, JsonSchema)]
    #[schemars(with = "String")]
    pub struct ProductName(String);

    impl ProductName {
        pub fn parse(raw: impl AsRef<str>) -> Result<Self, SuccessorError> {
            let raw = raw.as_ref();
            let valid = !raw.is_empty()
                && raw.len() <= 63
                && raw
                    .bytes()
                    .all(|byte| byte.is_ascii_lowercase() || byte.is_ascii_digit() || byte == b'-')
                && raw.bytes().next().is_some_and(|byte| byte.is_ascii_alphanumeric())
                && raw.bytes().last().is_some_and(|byte| byte.is_ascii_alphanumeric());
            if !valid {
                return Err(SuccessorError::InvalidProductName { raw: raw.to_string() });
            }
            Ok(Self(raw.to_string()))
        }

        pub fn as_str(&self) -> &str {
            &self.0
        }
    }

    impl fmt::Display for ProductName {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            f.write_str(&self.0)
        }
    }

    impl<'de> Deserialize<'de> for ProductName {
        fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
        where
            D: Deserializer<'de>,
        {
            Self::parse(String::deserialize(deserializer)?).map_err(serde::de::Error::custom)
        }
    }

    #[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, JsonSchema)]
    #[serde(rename_all = "camelCase", deny_unknown_fields)]
    pub struct ProductReleaseId {
        product: ProductName,
        version: Version,
    }

    #[derive(Deserialize)]
    #[serde(rename_all = "camelCase", deny_unknown_fields)]
    struct ProductReleaseIdWire {
        product: ProductName,
        version: Version,
    }

    impl ProductReleaseId {
        pub fn new(product: ProductName, version: Version) -> Result<Self, SuccessorError> {
            if version.grammar() != VersionGrammar::SemVer {
                return Err(SuccessorError::NonSemverProductVersion {
                    version: Box::new(version),
                });
            }
            Ok(Self { product, version })
        }

        pub fn from_coordinated_versions(
            product: ProductName,
            versions: impl IntoIterator<Item = Version>,
        ) -> Result<Self, SuccessorError> {
            let mut versions = versions.into_iter();
            let Some(version) = versions.next() else {
                return Err(SuccessorError::EmptyCoordinatedRoster);
            };
            let release = Self::new(product, version.clone())?;
            for candidate in versions {
                if candidate.grammar() != VersionGrammar::SemVer {
                    return Err(SuccessorError::NonSemverProductVersion {
                        version: Box::new(candidate),
                    });
                }
                if candidate != version {
                    return Err(SuccessorError::DivergentCoordinatedVersion {
                        expected: Box::new(version),
                        found: Box::new(candidate),
                    });
                }
            }
            Ok(release)
        }

        pub fn product(&self) -> &ProductName {
            &self.product
        }

        pub fn version(&self) -> &Version {
            &self.version
        }

        pub fn tag(&self) -> String {
            format!("{}@{}", self.product, self.version.render())
        }
    }

    impl PartialOrd for ProductReleaseId {
        fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
            Some(self.cmp(other))
        }
    }

    impl Ord for ProductReleaseId {
        fn cmp(&self, other: &Self) -> Ordering {
            (&self.product, version_ord_key(&self.version)).cmp(&(&other.product, version_ord_key(&other.version)))
        }
    }

    impl<'de> Deserialize<'de> for ProductReleaseId {
        fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
        where
            D: Deserializer<'de>,
        {
            let wire = ProductReleaseIdWire::deserialize(deserializer)?;
            Self::new(wire.product, wire.version).map_err(serde::de::Error::custom)
        }
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, JsonSchema)]
    #[serde(rename_all = "kebab-case")]
    pub enum ProductTarget {
        #[serde(rename = "aarch64-apple-darwin")]
        Aarch64AppleDarwin,
        #[serde(rename = "x86_64-unknown-linux-musl")]
        X86_64UnknownLinuxMusl,
        #[serde(rename = "aarch64-unknown-linux-musl")]
        Aarch64UnknownLinuxMusl,
        #[serde(rename = "wasm32-wasip1")]
        Wasm32Wasip1,
    }

    impl ProductTarget {
        pub const ALL: [Self; 4] = [
            Self::Aarch64AppleDarwin,
            Self::X86_64UnknownLinuxMusl,
            Self::Aarch64UnknownLinuxMusl,
            Self::Wasm32Wasip1,
        ];

        pub const fn artifact_kind(self) -> ProductArtifactKind {
            match self {
                Self::Aarch64AppleDarwin
                | Self::X86_64UnknownLinuxMusl
                | Self::Aarch64UnknownLinuxMusl => ProductArtifactKind::NativeArchive,
                Self::Wasm32Wasip1 => ProductArtifactKind::MoonWasmPlugin,
            }
        }

        pub const fn file_name(self) -> &'static str {
            match self {
                Self::Aarch64AppleDarwin => "callisto-aarch64-apple-darwin.tar.gz",
                Self::X86_64UnknownLinuxMusl => "callisto-x86_64-unknown-linux-musl.tar.gz",
                Self::Aarch64UnknownLinuxMusl => "callisto-aarch64-unknown-linux-musl.tar.gz",
                Self::Wasm32Wasip1 => "callisto-moon-wasm32-wasip1.wasm",
            }
        }
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, JsonSchema)]
    #[serde(rename_all = "camelCase")]
    pub enum ProductArtifactKind {
        NativeArchive,
        MoonWasmPlugin,
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, JsonSchema)]
    #[serde(rename_all = "camelCase")]
    pub enum RegistryArtifactFormat {
        CargoCrate,
        NpmTarball,
        PythonWheel,
        PythonSdist,
    }

    /// The graph-derived, closed registry portion of the coordinated decision.
    #[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, JsonSchema)]
    #[serde(rename_all = "camelCase", deny_unknown_fields)]
    pub struct ApprovedRegistryPackage {
        package: ReleasePackageId,
        #[serde(flatten)]
        registry: RegistryBindingId,
        format: RegistryArtifactFormat,
    }

    #[derive(Deserialize)]
    #[serde(rename_all = "camelCase", deny_unknown_fields)]
    struct ApprovedRegistryPackageWire {
        package: ReleasePackageId,
        #[serde(flatten)]
        registry: RegistryBindingId,
        format: RegistryArtifactFormat,
    }

    impl ApprovedRegistryPackage {
        pub fn new(
            package: ReleasePackageId,
            registry: RegistryBindingId,
            format: RegistryArtifactFormat,
        ) -> Result<Self, SuccessorError> {
            if !format_matches_ecosystem(format, package.ecosystem()) {
                return Err(SuccessorError::RegistryFormatMismatch);
            }
            Ok(Self {
                package,
                registry,
                format,
            })
        }

        pub fn package(&self) -> &ReleasePackageId {
            &self.package
        }

        pub fn registry(&self) -> &RegistryBindingId {
            &self.registry
        }

        pub fn format(&self) -> RegistryArtifactFormat {
            self.format
