            match self {
                Self::RegistryPackage { provenance_policy, .. }
                | Self::ProductAsset { provenance_policy, .. }
                | Self::ChecksumManifest { provenance_policy, .. }
                | Self::ReleaseMetadata { provenance_policy, .. } => provenance_policy,
            }
