            &self.destination
        }

        pub fn registry_packages(&self) -> &[ApprovedRegistryPackage] {
            &self.registry_packages
        }

        pub fn operations(&self) -> &[ReleaseOperation] {
            &self.operations
        }

        pub fn slots(&self) -> &[ReleaseArtifactSlot] {
            &self.slots
        }

        pub fn digest(&self) -> &IntentDigest {
