}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct ReleaseArtifactManifestWire {
    schema_version: u8,
    intent_digest: IntentDigest,
    source_commit: CommitSha,
    entries: Vec<ReleaseArtifactEntry>,
}

impl ReleaseArtifactManifest {
    const SCHEMA_VERSION: u8 = 1;

    pub fn complete(intent: &ReleaseIntent, payloads: &ValidatedPayloadEntries) -> Result<Self, SuccessorError> {
        payloads.validate_for(intent)?;
        let metadata = ReleaseDistributionMetadataV1::from_payloads(intent, payloads)?;
        let metadata_bytes = metadata.canonical_json();
        let metadata_slot = intent
            .slots
            .iter()
            .find(|slot| matches!(slot, ReleaseArtifactSlot::ReleaseMetadata { .. }))
            .expect("closed intent has metadata slot")
            .clone();
        let metadata_entry = generated_entry(intent, metadata_slot, metadata_bytes);
        let checksum_bytes = canonical_checksum_bytes(&payloads.entries, &metadata_entry)?;
        let checksum_slot = intent
            .slots
            .iter()
            .find(|slot| matches!(slot, ReleaseArtifactSlot::ChecksumManifest { .. }))
            .expect("closed intent has checksum slot")
            .clone();
        let checksum_entry = generated_entry(intent, checksum_slot, checksum_bytes);
        let mut entries = payloads.entries.clone();
        entries.extend([metadata_entry, checksum_entry]);
        entries.sort_by(|left, right| left.slot.cmp(&right.slot));
        validate_complete_entries(intent, &entries)?;
        Ok(Self {
            schema_version: Self::SCHEMA_VERSION,
            intent_digest: intent.digest.clone(),
            source_commit: intent.source_commit.clone(),
            entries,
        })
    }

    pub fn validate_for_intent(&self, intent: &ReleaseIntent) -> Result<(), SuccessorError> {
        if self.schema_version != Self::SCHEMA_VERSION
            || self.intent_digest != intent.digest
            || self.source_commit != intent.source_commit
        {
            return Err(SuccessorError::MismatchedManifest);
        }
        let payloads = ValidatedPayloadEntries::new(
            intent,
            self.entries
                .iter()
                .filter(|entry| {
                    matches!(
                        entry.slot,
                        ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ProductAsset { .. }
                    )
                })
                .cloned()
                .collect(),
        )?;
        (*self == Self::complete(intent, &payloads)?)
            .then_some(())
            .ok_or(SuccessorError::MismatchedManifest)
    }

    pub fn intent_digest(&self) -> &IntentDigest {
        &self.intent_digest
    }

    pub fn source_commit(&self) -> &CommitSha {
        &self.source_commit
    }

    pub fn entries(&self) -> &[ReleaseArtifactEntry] {
        &self.entries
    }
}

fn generated_entry(intent: &ReleaseIntent, slot: ReleaseArtifactSlot, bytes: Vec<u8>) -> ReleaseArtifactEntry {
    ReleaseArtifactEntry {
        digest: ArtifactDigest::from_bytes(&bytes),
        byte_length: bytes.len() as u64,
        source_commit: intent.source_commit.clone(),
        provenance: slot.policy().clone(),
        slot,
    }
}

fn validate_complete_entries(
    intent: &ReleaseIntent,
    entries: &[ReleaseArtifactEntry],
) -> Result<(), SuccessorError> {
    if entries.windows(2).any(|pair| pair[0].slot == pair[1].slot)
        || entries.iter().map(|entry| &entry.slot).ne(intent.slots.iter())
        || entries
            .iter()
            .any(|entry| entry.source_commit != intent.source_commit || entry.provenance != *entry.slot.policy())
    {
        return Err(SuccessorError::MismatchedManifest);
    }
    Ok(())
}

impl<'de> Deserialize<'de> for ReleaseArtifactManifest {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let wire = ReleaseArtifactManifestWire::deserialize(deserializer)?;
        if wire.schema_version != Self::SCHEMA_VERSION {
            return Err(serde::de::Error::custom(
                "unsupported successor artifact manifest schema",
            ));
        }
        Ok(Self {
            schema_version: wire.schema_version,
            intent_digest: wire.intent_digest,
            source_commit: wire.source_commit,
            entries: wire.entries,
        })
    }
}

