/// Only externally supplied bytes: registry packages and product payloads.
/// Metadata and checksums are generated below, never accepted as an
/// intermediate caller-supplied "full" manifest.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ValidatedPayloadEntries {
    intent_digest: IntentDigest,
    source_commit: CommitSha,
    slots: Vec<ReleaseArtifactSlot>,
    entries: Vec<ReleaseArtifactEntry>,
}

impl ValidatedPayloadEntries {
    pub fn new(intent: &ReleaseIntent, mut entries: Vec<ReleaseArtifactEntry>) -> Result<Self, SuccessorError> {
        entries.sort_by(|left, right| left.slot.cmp(&right.slot));
        let expected = intent.slots.iter().filter(|slot| {
            matches!(
                slot,
                ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ProductAsset { .. }
            )
        });
        if entries.windows(2).any(|pair| pair[0].slot == pair[1].slot)
            || entries.iter().map(|entry| &entry.slot).ne(expected)
            || entries.iter().any(|entry| {
                entry.source_commit != intent.source_commit || entry.provenance != *entry.slot.policy()
            })
        {
            return Err(SuccessorError::MismatchedManifest);
        }
        Ok(Self {
            intent_digest: intent.digest.clone(),
            source_commit: intent.source_commit.clone(),
            slots: entries.iter().map(|entry| entry.slot.clone()).collect(),
            entries,
        })
    }

    fn validate_for(&self, intent: &ReleaseIntent) -> Result<(), SuccessorError> {
        let expected = intent.slots.iter().filter(|slot| {
            matches!(
                slot,
                ReleaseArtifactSlot::RegistryPackage { .. } | ReleaseArtifactSlot::ProductAsset { .. }
            )
        });
        if self.intent_digest != intent.digest
            || self.source_commit != intent.source_commit
            || self.slots.iter().ne(expected)
        {
            return Err(SuccessorError::MismatchedPayloadIntent);
        }
        Ok(())
    }

    pub fn entries(&self) -> &[ReleaseArtifactEntry] {
        &self.entries
    }
}

