        let checksum_slot = intent
            .slots
            .iter()
            .find(|slot| matches!(slot, ReleaseArtifactSlot::ChecksumManifest { .. }))
            .expect("closed intent has checksum slot")
            .clone();
        let checksum_entry = generated_entry(intent, checksum_slot, checksum_bytes);
