        Self::new(intent, expected, self.operations.clone()).map(|_| ())
    }

    pub fn intent_digest(&self) -> &IntentDigest {
        &self.intent_digest
    }

    pub fn operations(&self) -> &[ObservedOperation] {
        &self.operations
    }
}

