        Self::complete_with_generated_files(intent, payloads).map(ReleaseArtifactBundle::into_manifest)
    }

    pub fn complete_with_generated_files(
        intent: &ReleaseIntent,
        payloads: &ValidatedPayloadEntries,
    ) -> Result<ReleaseArtifactBundle, SuccessorError> {
        payloads.validate_for(intent)?;
        let metadata = ReleaseDistributionMetadataV1::from_payloads(intent, payloads)?;
